public async Task GetNearestShelters_OrdersSheltersByProximity()
    {
        var context = GetInMemoryContext();
        context.Shelters.Add(new Shelter
        {
            Name = "Far Shelter",
            Location = "Kandy",
            TotalCapacity = 200,
            CurrentOccupancy = 10,
            Status = "Active",
            Latitude = 7.2906,
            Longitude = 80.6337
        });

        context.Shelters.Add(new Shelter
        {
            Name = "Near Shelter",
            Location = "Colombo Fort",
            TotalCapacity = 100,
            CurrentOccupancy = 20,
            Status = "Active",
            Latitude = 6.9344,
            Longitude = 79.8428
        });

        await context.SaveChangesAsync();

        var service = new GeolocationService(context);
        var nearest = await service.GetNearestSheltersAsync(6.9271, 79.8612, limit: 2);

        Assert.Equal(2, nearest.Count);
        Assert.Equal("Near Shelter", nearest[0].Name);
        Assert.True(nearest[0].DistanceKm < nearest[1].DistanceKm);
    }
}

public async Task AdjustStock_ReturnsBadRequest_WhenResultingQuantityIsNegative()
    {
        var context = GetInMemoryContext();
        var item = new InventoryItem
        {
            ItemName = "Medical Bandages",
            Category = "Medical",
            Quantity = 10,
            MinimumThreshold = 5,
            Status = "InStock"
        };
        context.InventoryItems.Add(item);
        await context.SaveChangesAsync();

        var controller = new InventoryController(context);
        var dto = new AdjustStockDto { QuantityAdjustment = -20 };

        var result = await controller.AdjustStock(item.Id, dto);

        Assert.IsType<Microsoft.AspNetCore.Mvc.BadRequestObjectResult>(result);
    }
}

public async Task AdjustStock_SubtractsQuantity_UpdatesStatus()
